Lemma after_del (fx : FPState) R M model (B A a0 : Z) (cr' : credit) :
  PMSP.model_ok model -> z = c -> 0 < c -> A = 2 * c ->
  getr R (reg 2) = Z_to_bv 64 (S - 64) -> getr R (reg 8) = Z_to_bv 64 o -> getr R (reg 10) = Z_to_bv 64 a0 -> getr R (reg 20) = Z_to_bv 64 (B + c + 1) ->
  0 <= a0 < 2 ^ 64 ->
  kept0 R -> saves M -> mem_ok M ->
  L5.u64_at RSEGS M o B -> L5.u64_at RSEGS M (o + 16) (B + A) ->
  L5.defined M B A -> block_range L B A -> (NESK.sp_cap P A /\ A <= NESK.sp_nmax P) ->
  hi_heap HI ((B, A) :: LBX) cr' M (m_vmmaps model) -> model_but_vm model0 model ->
  PMSP.credit_keep cr0 cr' (NESK.sink_pot P c) (NESK.sink_pot P A) ->
