Definition ledger_rows : Prop :=
  NESK.push_back_spec RSEGS AD AE L HI PMSP.T3 PMSP.T4 NESK.PME /\ NECS.enc_ok RSEGS AD AQ AE L HI NESK.PME /\ PNV.vis_ok RSEGS AD AQ AE L HI
  /\ PNRN.read_item_spec RSEGS AD AQ AE L HI /\ PNRN.parse_spec RSEGS AD AQ AE L HI /\ PQR.reset_spec RSEGS AD AQ L HI
  /\ PQRH.reader_ctor_spec RSEGS AD AQ L HI /\ PQRH.reader_dtor_spec RSEGS AD AQ L HI.
Lemma ledger_rows_ok : ledger_rows.
Proof. exact (conj push_back (conj ENC (conj VIS (conj read_item (conj parse (conj reset (conj reader_ctor reader_dtor))))))). Qed.
